// Every number that decides how hard things hit and how long things last, in one
// place. The Bedrock scripts get these through scripts/data.js and the Java mod
// through data/lavagun/rules.json (both generated by tools/build.mjs).
//
// Damage is in health points (1 heart = 2), times are in seconds.

export const RULES = {
  guns: {
    lava_pistol: {
      ammo: 'lava_cell', ammoPerShot: 1, projectile: 'lava_bolt', cooldown: 0.4,
      speed: 3.2, gravity: 0.01, damage: 4, fire: 3,
    },
    lava_gun: {
      ammo: 'lava_cell', ammoPerShot: 2, projectile: 'lava_blob', cooldown: 1.5,
      speed: 1.6, gravity: 0.05, damage: 8, fire: 5,
      // A direct hit on a mob shuts it in obsidian; a miss splashes lava where it lands.
      encase: true,
      splash: { radius: 2, damage: 4, fire: 3, lava: true },
    },
    obsidian_gun: {
      ammo: 'lava_cell', ammoPerShot: 2, projectile: 'obsidian_blob', cooldown: 1.0,
      speed: 1.6, gravity: 0.05, damage: 6, fire: 3,
      // Where it lands the lava sets into obsidian that stays: the block hit and the four next to it.
      obsidian: { radius: 1 },
    },
  },
  sprayer: {
    id: 'magma_sprayer', ammo: 'magma_charge', range: 6, cone: 25,
    // One pulse every 4 ticks (5 a second); one magma charge lasts 2 seconds of spraying.
    pulseTicks: 4, damage: 1, fire: 4, ticksPerCharge: 40,
  },
  // The lava cannon: put it down, then use it to fire a ball of lava that stays where
  // it lands. Sneak and use to pick a range from 1 to 5; the ranges are in blocks on
  // flat ground, fired at `angle` degrees.
  cannon: {
    id: 'lava_cannon', ammo: 'lava_cell', ammoPerShot: 2, cooldown: 2, projectile: 'lava_ball',
    ranges: [8, 16, 24, 32, 40], startRange: 3, angle: 25, gravity: 0.05, muzzle: { forward: 1.3, up: 1.1 },
    damage: 8, fire: 5, health: 20,
  },
  grenade: { id: 'magma_grenade', damage: 6, radius: 3, fire: 4, ring: 2 },
  sword: { fire: 4 },
  golem: { slam: 10, slamRadius: 3, slamLava: 1 },

  // Lava, obsidian and basalt placed by the add-on are only there for a while.
  temporary: {
    lava: 6,
    shell: 5,
    walker: 4,
  },
  // Obsidian shell: how big a mob can be shut in, and how long before it can be shut in again.
  shell: {
    maxWidth: 3, maxHeight: 4, immunity: 3, burnAfter: 5,
    // Too big, or too important, to be shut in.
    exempt: ['minecraft:ender_dragon', 'minecraft:wither', 'minecraft:warden', 'minecraft:ravager', 'minecraft:elder_guardian', 'minecraft:ghast', 'minecraft:happy_ghast'],
  },
  // Mobs that take no fire damage: only the hit itself hurts them.
  fireproof: ['minecraft:blaze', 'minecraft:strider', 'minecraft:magma_cube', 'minecraft:ghast', 'minecraft:wither_skeleton', 'minecraft:zombified_piglin', 'lavagun:magma_golem', 'lavagun:lava_slug'],

  // A block state can't have more than 16 values on Bedrock: 0–12 buckets, shown in 4 steps.
  tank: { capacity: 12, stages: 4, cellsPerBucket: 8 },
  slug: { milkCooldown: 300 },
  armor: { walkerRadius: 2 },
};
